el><label>Maximum shares<input name="maximum_purchase_quantity" value="<?= e($value('maximum_purchase_quantity')) ?>"></label><label>Maximum user holding<input name="maximum_user_holding" value="<?= e($value('maximum_user_holding')) ?>"></label><label>Quantity decimal places<input type="number" min="0" max="8" name="quantity_decimal_places" value="<?= e($value('quantity_decimal_places',0)) ?>"></label><label>Profit type<select name="profit_type"><option value="PERCENTAGE"<?= $value('profit_type')==='PERCENTAGE'?' selected':'' ?>>Percentage</option><option value="FIXED"<?= $value('profit_type')==='FIXED'?' selected':'' ?>>Fixed</option></select></label><label>Projected profit<input name="projected_profit_value" value="<?= e($value('projected_profit_value','0')) ?>" required></label><label>Fixed-profit basis<select name="fixed_profit_basis"><option value="PER_SHARE">Per share</option><option value="PER_INVESTMENT">Per investment</option></select></label><label>Duration<input type="number" min="1" name="duration_value" value="<?= e($value('duration_value','30')) ?>"></label><label>Duration unit<select name="duration_unit"><?php foreach(['DAYS','WEEKS','MONTHS','YEARS']as$unit):?><option<?= $value('duration_unit')===$unit?' selected':'' ?>><?= $unit ?></option><?php endforeach;?></select></label></div><label>Reason for pricing/term change<textarea name="change_reason"></textarea></label><div class="checks"><label><input type="checkbox" name="fractional_shares_allowed" value="1"<?= $value('fractional_shares_allowed')?' checked':'' ?>> Fractional shares allowed</label><label><input type="checkbox" name="selling_enabled" value="1"<?= $value('selling_enabled')?' checked':'' ?>> Share sale requests enabled</label><label><input type="checkbox" name="offering_active" value="1"<?= $value('offering_active')?' checked':'' ?>> Offering active</label><label><input type="checkbox" name="offering_featured" value="1"<?= $value('offering_featured')?' checked':'' ?>> Featured offering</label><label><input type="checkbox" name="is_featured" value="1"<?= $value('is_featured')?' checked':'' ?>> Feature company</label></div><label>Company status<select name="status"><?php foreach(['DRAFT','ACTIVE','SUSPENDED','ARCHIVED']as$status):?><option<?= $value('status')===$status?' selected':'' ?>><?= $status ?></option><?php endforeach;?></select></label><input type="hidden" name="sort_order" value="<?= e($value('sort_order',0)) ?>"><button class="button">Save company and offering</button></form><?php if(isset($company['id'])):?><form method="post" action="<?= e(route('admin.companies.archive',['company'=>$company['id']])) ?>"><?= app('csrf')->input() ?><input type="hidden" name="action" value="<?= $company['status']==='ARCHIVED'?'restore':'archive' ?>"><button class="button button-danger"><?= $company['status']==='ARCHIVED'?'Restore company':'Archive company' ?></button></form><?php endif;?>
